function validate(input) {
  const [{ Project = [], Employee = [] }] = input;
  const staff = new Set();
  for (const row of Employee) {
    if (row.some((v) => v === null)) return 'Employee rows may not contain null.';
    if (staff.has(row[0])) return `employee_id ${row[0]} appears twice in Employee.`;
    if (row[2] < 0) return `Employee ${row[0]} has negative experience_years.`;
    staff.add(row[0]);
  }
  const pairs = new Set();
  for (const [project, employee] of Project) {
    if (project === null || employee === null) return 'Project rows may not contain null.';
    if (!staff.has(employee)) return `Project ${project} names unknown employee ${employee}.`;
    const key = `${project}|${employee}`;
    if (pairs.has(key)) return `(project ${project}, employee ${employee}) appears twice in Project.`;
    pairs.add(key);
  }
  return null;
}

