function generate(rand, size) {
  const names = ['Khaled', 'Ali', 'John', 'Doe', 'Mona', 'Sara', 'Omar', 'Lina'];
  const small = size === 'small';
  const people = small ? Math.floor(rand() * 6) : 1000;
  const Employee = [];
  for (let id = 1; id <= people; id++) Employee.push([id, names[Math.floor(rand() * names.length)], Math.floor(rand() * (small ? 4 : 30))]);
  const Project = [];
  if (people > 0) {
    const projects = small ? 1 + Math.floor(rand() * 4) : 120;
    const target = small ? Math.floor(rand() * 9) : 2000;
    const seen = new Set();
    for (let tries = 0; Project.length < target && tries < target * 3; tries++) {
      const project = small ? projects - Math.floor(rand() * projects) : 1 + Math.floor(rand() * projects);
      const employee = 1 + Math.floor(rand() * people);
      if (seen.has(`${project}|${employee}`)) continue;
      seen.add(`${project}|${employee}`);
      Project.push([project, employee]);
    }
  }
  return [{ Project, Employee }];
}
